S=$0;read Q;read T;read K||K=0;K=${K:-0};python3 -c 'import sys,json,os;q=sys.argv[1];T=max(1,int(sys.argv[2]));k=sys.argv[3];S=sys.argv[4];J=lambda x:json.dumps(x,separators=(",",":"));A="RMZ_CGZ_PATH_2K_TRUE_ONELINER.sh";B="RMZ_CGZ_ANSELM_ONTO_PCC_NOSHA_TRUE_ONELINER.sh";RF=[A,B];C=lambda s:[w for w in("".join(c.lower()if c.isalnum()else" "for c in s).split())if w];R=C(q);W=R or["void"];qn=" ".join(R);tag="path";G=sum((b+1)*257**i for i,b in enumerate(J([qn,T,k,tag,RF]).encode()));KV=sum((i+1)*(b+1)for i,b in enumerate(k.encode()));SR=sum((i+1)*(b+1)for i,b in enumerate(open(S,"rb").read()if os.path.exists(S)else b""))%10**18;b=min(T,12);N=(1<<(b+1))-1;M=997+G%97;F=lambda j:(G+SR*j+j*j+KV+len(A)+len(B))%M;O=min((F(j),j)for j in range(N));ttl="Bounded %s Logic V%s"%(W[0].title(),k);cl="s=1/2+i%d"%(G%1000000);V=int(len(R)>0 and qn==" ".join(R)and O==min((F(j),j)for j in range(N))and RF==[A,B]and ttl=="Bounded %s Logic V%s"%(W[0].title(),k));D={"P":"RMZCGZ2K","UTL":"RMZ-UTL/1","NL":"RMZ-NL/1","MATH":"RMZ-MATH/1","MML":"RMZ-MML/1","LOGIC":"RMZ-LK/1","REF":RF,"REF_CERT":V,"FORALL":"pi<N=>REF(PATH,ONTO)","CONS":V,"COMP":V,"Q_RAW":q,"Q_NORM":qn,"TOKENS":R,"INTENT":tag,"AX":"NL->MATH->MML;REF","GRAM":"RAW TOK G CL TM REF CERT","VM":"qRef>qNL>qMath>qMML>qVerify>qHalt","VERIFY":"recalc QN/G/OPT/TITLE/REF","SELF":SR,"ORIGIN":SR,"D0":1,"VARIANT":k,"SALT":KV,"BND":b,"ENUM":N,"G":str(G),"CL":cl,"OPT":O,"TITLE":ttl,"TT":"z0;RefC;NL;TZC;NZO;MATH;MML;certC","V":V,"PCC":V,"ZE":V,"Bd":"bounded refs; not full NL/RH/halt"};open("CGZ.clcert","w").write(J(D)+"\n");print(J({"P":D["P"],"TITLE":ttl,"UTL":D["UTL"],"LOGIC":D["LOGIC"],"REF_CERT":V,"CONS":V,"COMP":V,"PCC":V,"ZE":V,"cert":"CGZ.clcert","bytes":"<2048"}))' "$Q" "$T" "$K" "$S"